// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"ja","term":"ブロックチェーン","aka":["Blockchain","分散型台帳"],"short":"ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。","body":["各ブロックには一定期間の取引データと、直前のブロックのハッシュ値（データから計算される指紋のような値）が含まれます。過去のブロックを1文字でも書き換えるとハッシュ値が変わり、後に続くすべてのブロックとの整合性が崩れるため、改ざんが非常に難しい仕組みになっています。",["台帳は特定の会社のサーバーではなく、世界中の",["ノード","node"],"（参加コンピューター）が同じコピーを持ちます。新しいブロックを誰が追加するかは、",["ビットコイン","bitcoin"],"なら",["プルーフ・オブ・ワーク","proof-of-work"],"、",["イーサリアム","ethereum"],"なら",["プルーフ・オブ・ステーク","proof-of-stake"],"といったコンセンサスの仕組みで決まります。"],["トレーダーにとって重要なのは、送金がブロックに取り込まれて初めて確定するという点です。取引所への入金に「承認回数」が必要なのはこのためで、必要な",["承認数","block-confirmations"],"はチェーンや取引所ごとに異なります。また、ブロックチェーン上の送金は原則として取り消せません。"]],"example":"例えば、あなたがビットコインを取引所に入金し、その取引所が3承認を求めているとします。ビットコインのブロックは平均約10分ごとに生成されるので、最初のブロックに取り込まれてから3承認に達するまでの目安は約30分です。手数料を低く設定しすぎて混雑時に取り込みが遅れると、待ち時間はさらに延びます。","mistakes":["ブロックチェーン上の送金は銀行振込のように後から取り消せると思い込むこと。","「ブロックチェーン」と名の付くプロジェクトなら安全だと判断し、運営体制や中身を確認しないこと。","取引所内の振替もすべてブロックチェーンに記録されると誤解すること。"],"faq":[{"q":"ブロックチェーンと暗号資産は同じものですか？","a":"同じではありません。ブロックチェーンは記録の仕組みで、暗号資産はその上で発行・移転される資産です。ブロックチェーンは暗号資産以外の用途にも使われます。"},{"q":"ブロックチェーンは絶対に改ざんできないのですか？","a":"大規模なチェーンでは改ざんは現実的に極めて困難ですが、理論上は不可能ではありません。参加者が少ない小規模チェーンでは、計算力やステークの過半数を握る「51%攻撃」のリスクが相対的に高くなります。"},{"q":"ブロックチェーンの取引記録は誰でも見られますか？","a":"ビットコインやイーサリアムのようなパブリックチェーンでは、ブロックエクスプローラーで誰でも取引履歴を確認できます。アドレスと個人は直接結び付いて表示されませんが、完全な匿名ではありません。"}],"title":"ブロックチェーンとは？仕組みと意味をわかりやすく解説","description":"ブロックチェーンの意味、改ざんが難しい理由、取引所への入金に承認回数が必要な理由を初心者向けにわかりやすく解説します。","related":[["cryptocurrency","暗号資産（仮想通貨）","暗号資産（仮想通貨）とは、ブロックチェーンなどの技術で発行・管理され、インターネット上で個人間で直接やり取りできるデジタル資産のことです。"],["proof-of-work","プルーフ・オブ・ワーク（PoW）","プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。"],["proof-of-stake","プルーフ・オブ・ステーク（PoS）","プルーフ・オブ・ステーク（PoS）とは、暗号資産を担保として預け入れ（ステーク）したバリデーターが、ブロックの提案と検証を担うコンセンサスの仕組みです。"],["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"],["block-explorer","ブロックエクスプローラー","ブロックエクスプローラーとは、ブロックチェーン上の取引、アドレスの残高、ブロックの情報を検索して閲覧できるウェブサービスのことです。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"ja","term":"取引量（出来高）","aka":["出来高","売買高","ボリューム","trading volume"],"short":"取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。","body":[["取引量は、市場でどれだけ活発に売買が行われているかを示す数字です。取引所やデータサイトでは「24時間取引量」として、枚数ベースまたはUSDや円などの金額ベースで表示されるのが一般的です。チャート下部の棒グラフも、各",["ローソク足","candlestick-chart"],"の期間中の出来高を表しています。"],"トレーダーが取引量を見る理由は、価格の動きにどれだけの参加者が伴っているかを知るためです。出来高を伴って節目を抜けた動きは注目されやすく、出来高の少ない値動きは続きにくいと見られることがあります。ただしこれは傾向であって、必ずそうなるわけではありません。",["注意点として、取引量は取引所の自己申告であり、一部の取引所では見せかけの売買で水増しされてきた歴史があります。また、現物の取引量と先物の取引量は別物です。先物は",["レバレッジ","leverage"],"を使うため取引量が膨らみやすく、",["建玉","open-interest"],"（未決済建玉）とあわせて読む必要があります。"]],"example":"あるトークンの価格が1日中2.50 USDT前後で、24時間に400万枚が売買されたとします。金額ベースの取引量は約2.5×400万＝1,000万 USDTです。翌日に価格が2.80 USDTまで上がり、出来高が1,200万枚に増えれば、前日の3倍の参加者が動いたことになります。一方、出来高が100万枚のまま2.80 USDTまで上がった場合は、少ない売買で価格が動いたと読めます。","mistakes":["取引所が表示する取引量をそのまま信用し、板の厚みや他の取引所との比較をしない。","現物と先物の取引量を混同し、先物の巨大な数字を現物の需要だと考える。","出来高が増えたことだけを見て、価格が上がるか下がるかまで判断できると思う。"],"faq":[{"q":"取引量と時価総額の違いは何ですか？","a":"時価総額は価格と流通量を掛けた、その時点の規模です。取引量は一定期間に実際に売買された量で、市場の活発さを表します。"},{"q":"取引量が多いほど安全な銘柄ですか？","a":"取引量が多いと売買しやすい傾向はありますが、安全性を示すものではありません。水増しされた取引量もあるため、板の厚みもあわせて確認してください。"}],"title":"取引量（出来高）とは？暗号資産での意味と見方","description":"暗号資産の取引量（出来高）の意味、チャートでの読み方、現物と先物の違い、水増しされた取引量に注意すべき理由を解説します。","related":[["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。"],["open-interest","建玉（未決済建玉・オープンインタレスト）","建玉（オープンインタレスト）とは、先物やオプションで、まだ決済されずに残っている契約の総数（または総額）のことで、市場にどれだけの資金がポジションとして入っているかを示します。"],["wash-trading","ウォッシュトレード（仮装売買）","ウォッシュトレード（仮装売買）とは、同じ人物や協力関係にある者同士が自分で買って自分で売り、実態のない取引を作って取引量や価格を偽装する行為です。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"ja","term":"ポジションサイジング（建玉管理）","aka":["ポジションサイズ","資金管理","position sizing"],"short":"ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。","body":[["多くのトレーダーは、1回の取引で失ってもよい金額を口座資金の1〜2%などに決めておきます。次に、エントリー価格から",["損切り","stop-loss"],"価格までの値幅を決めます。この2つから「損切りに引っかかったときにちょうど許容損失になる数量」を計算するのがポジションサイジングです。式は、数量＝許容損失額÷1単位あたりの損失額です。"],["大切なのは、",["レバレッジ","leverage"],"の倍率ではなく損失額から数量を決めることです。レバレッジを上げても、同じ数量なら損切り時の損失額は変わりません。変わるのは必要な証拠金の量と、",["強制ロスカット","liquidation"],"までの距離です。損切りより先に",["ロスカット価格","liquidation-price"],"が来ないかは必ず確認してください。"],["ポジションサイズを一定のルールで決めると、連敗しても口座が大きく減りにくくなり、1回の負けで感情的になることも減ります。手数料や",["スリッページ","slippage"],"の分だけ実際の損失は少し大きくなるので、余裕を見ておくのが現実的です。"]],"example":["口座資金が5,000 USDTで、1回の許容損失を2%の100 USDTとします。SOLを150 USDTで買い、損切りを142 USDTに置くなら、1枚あたりの損失は8 USDTです。数量は100÷8＝12.5 SOLで、想定元本は1,875 USDTになります。これを5倍レバレッジで建てれば",["必要証拠金","initial-margin"],"は375 USDTですが、損切り時の損失は同じ100 USDTです。"],"mistakes":["損切り幅を決めずに、なんとなく残高の半分などでポジションを建てる。","レバレッジの倍率がリスクの大きさそのものだと考え、数量と損切り幅を確認しない。","損切り価格より先に強制ロスカット価格が来る設定になっていることに気づかない。"],"faq":[{"q":"1回の取引でどれくらいのリスクを取るのが一般的ですか？","a":"口座資金の1〜2%程度を目安にする人が多いですが、決まった正解はありません。連敗しても続けられる水準に設定することが大切です。"},{"q":"レバレッジを上げるとポジションサイズも大きくなりますか？","a":"レバレッジは必要な証拠金を減らすだけで、数量は自分で決めます。ただし同じ証拠金で大きな数量を建てやすくなるため、損失額を必ず計算してください。"}],"title":"ポジションサイジングとは？適切な取引量の決め方","description":"ポジションサイジングの意味と計算式、許容損失と損切り幅から取引数量を決める方法、レバレッジとの関係を具体例で解説します。","related":[["risk-reward-ratio","リスクリワードレシオ（損益比率）","リスクリワードレシオとは、1回の取引で想定する損失額（リスク）と利益額（リワード）の比率のことで、例えば損失100に対して利益200なら1対2と表します。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"いくら買うか決める前に、いくら失えるかを決めよ"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"ja","term":"資金調達率（ファンディングレート）","aka":["ファンディングレート","資金調達率","FR","funding rate"],"short":"資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。","body":[[["無期限先物","perpetual-futures"],"には満期がないため、放っておくと先物価格が現物価格から大きく離れることがあります。そこで、先物価格が現物より高いときは資金調達率がプラスになり、",["ロング","long-and-short"],"がショートに支払います。逆に先物が安いときはマイナスになり、ショートがロングに支払います。支払いは取引所ではなくトレーダー同士の間で行われます。"],"精算間隔は多くの取引所で8時間ごとですが、取引所や銘柄によっては1時間、2時間、4時間ごとのものもあり、相場が荒れると間隔が短く変更されることもあります。支払い額は、想定元本×資金調達率で計算され、精算時刻にポジションを持っている人だけが対象になります。","資金調達率は市場の偏りを映す指標としても使われます。高いプラスが続くのはロングが過熱しているサイン、大きなマイナスはショートが偏っているサインと見られます。ただし、それだけで価格の方向は決まりません。"],"example":"BTCの無期限先物で想定元本20,000 USDTのショートを持ち、資金調達率が+0.03%、8時間ごとの精算だとします。ショートは1回あたり20,000×0.0003＝6 USDTを受け取り、1日3回で18 USDTです。1週間続けば126 USDTです。同じ条件でロングを持っていれば、逆に126 USDTを支払うことになります。","mistakes":["精算時刻を過ぎた直後にポジションを持っても、直前の精算分を受け取れると思う。","資金調達率を証拠金に対する率だと誤解し、実際は想定元本に掛かることを忘れる。","資金調達率が高いからといって、それだけで逆張りのポジションを取る。"],"faq":[{"q":"資金調達率がマイナスとはどういう意味ですか？","a":"先物価格が現物より安い状態で、ショートがロングに支払います。ショートが多く偏っていることを示す場合があります。"},{"q":"資金調達率は取引所に払う手数料ですか？","a":"いいえ、ロングとショートのトレーダー同士でやり取りされる支払いです。取引手数料とは別物です。"},{"q":"資金調達率はいつ発生しますか？","a":"取引所が決めた精算時刻にポジションを持っている場合に発生します。多くは8時間ごとですが、取引所や銘柄で異なります。"}],"title":"資金調達率（ファンディングレート）とは？仕組みと計算","description":"資金調達率（ファンディングレート）の仕組み、プラスとマイナスの意味、精算間隔と支払い額の計算方法を具体例でわかりやすく解説します。","related":[["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["funding-rate-arbitrage","資金調達率アービトラージ（FRアービトラージ）","資金調達率アービトラージとは、現物を買うと同時に同じ数量の無期限先物をショートし、価格変動の影響を打ち消しながら資金調達率の受け取りを狙う取引です。"],["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"],["index-price","インデックス価格","インデックス価格とは、複数の主要な現物取引所の価格を加重平均して算出した、その暗号資産の現物の基準価格のことで、マーク価格や資金調達率の計算に使われます。"],["open-interest","建玉（未決済建玉・オープンインタレスト）","建玉（オープンインタレスト）とは、先物やオプションで、まだ決済されずに残っている契約の総数（または総額）のことで、市場にどれだけの資金がポジションとして入っているかを示します。"]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"価格は横ばい、残高は減少？コストを意識して最終関門をクリアせよ"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"ja","term":"DeFi（分散型金融）","aka":["分散型金融","ディーファイ","DeFi"],"short":"DeFi（分散型金融）とは、銀行や取引所などの仲介者を通さず、ブロックチェーン上のスマートコントラクトで交換、貸し借り、利回り運用などを行う金融サービスの総称です。","body":[["代表的なものに、トークンを交換するDEX（Uniswapなど）、",["暗号資産","cryptocurrency"],"を貸し借りするレンディング（Aaveなど）、",["ステーブルコイン","stablecoin"],"、デリバティブ取引のプロトコルがあります。",["ウォレット","crypto-wallet"],"を接続すれば、口座開設なしで誰でも使えます。"],["ルールがコードとして公開され、取引は",["ブロックチェーン","blockchain"],"上で誰でも検証できます。資産は自分のウォレットで管理し、利用時だけ",["スマートコントラクト","smart-contract"],"に預ける形になります。"],["一方で、コードの脆弱性によるハッキング、価格情報（",["オラクル","oracle"],"）の操作、担保不足による清算、トークン承認を悪用した詐欺など、中央集権型の取引所とは違うリスクがあります。トラブル時に頼れるサポート窓口がない点も理解しておきましょう。"]],"example":"あなたがDeFiのレンディングで、2 ETHを担保に預けてUSDCを借りるとします。ETHが3,000ドルなら担保価値は6,000ドルで、担保掛目が80%なら最大4,800ドルまで借りられる計算です。ここで2,400ドル分だけ借りれば、担保価値の40%に抑えられます。ETHが下落して担保価値が借入額に対して不足すると、自動的に清算が実行されます。","mistakes":["高い利回りの表示だけを見て、スマートコントラクトのリスクを確認しないこと。","ガス代を考えず、少額で何度も取引して利益を手数料で失うこと。","DeFiにもカスタマーサポートがあると思い込み、偽サポートに連絡すること。"],"faq":[{"q":"DeFiと取引所（CeFi）の違いは何ですか？","a":"取引所では運営会社が資産を預かって取引を仲介しますが、DeFiではスマートコントラクトが自動で処理し、資産は自分のウォレットで管理します。便利さやサポートの有無、リスクの種類が異なります。"},{"q":"DeFiを始めるには何が必要ですか？","a":"ノンカストディアルウォレット、利用するチェーンのガス代用の暗号資産、運用したいトークンが必要です。最初は少額で操作に慣れるのが一般的です。"}],"title":"DeFi（分散型金融）とは？仕組みと主なリスク","description":"DeFi（分散型金融）の意味、DEXやレンディングなど代表的なサービス、中央集権型取引所との違いと特有のリスクを解説します。","related":[["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"],["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"],["total-value-locked","TVL（預かり資産総額）","TVLとは、DeFiのプロトコルやブロックチェーンに預けられている暗号資産の総額をドルなどで表した指標で、利用規模の目安として使われます。"],["defi-lending","DeFiレンディング","DeFiレンディングとは、スマートコントラクト上で暗号資産を貸し出して利息を得たり、担保を預けて別の暗号資産を借りたりできる仕組みです。"],["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"ja","term":"クロスチェーンブリッジ","aka":["ブリッジ","bridge","クロスチェーン送金"],"short":"クロスチェーンブリッジとは、異なるブロックチェーン間で暗号資産やデータを移動できるようにする仕組みで、たとえばイーサリアムのUSDCをレイヤー2に移すときに使われます。","body":[[["ブロックチェーン","blockchain"],"同士は直接やり取りできないため、ブリッジが仲介します。よく使われるのは、元のチェーンで資産をロックし、移動先のチェーンで同じ量の",["ラップトークン","wrapped-token"],"を発行する方式です。発行元自身が複数のチェーンでネイティブに発行・償還する方式もあります。"],"ブリッジには大量の資産がロックされるため、ハッキングの標的になりやすく、過去には大規模な被害も起きています。署名者の鍵が盗まれたり、コントラクトの検証に不備があったりすると、ロック資産が流出します。",["使う際は、公式のブリッジか実績のあるブリッジを選び、移動先のチェーンに",["ガス代","gas-fee"],"用の資産があるかを確認します。取引所を経由すれば、入金と別ネットワークでの出金で実質的にチェーンを移せる場合もあります。"]],"example":["あなたが",["イーサリアム","ethereum"],"上の1,000 USDCをArbitrumに移すとします。ブリッジでの手数料とイーサリアムのガス代が合計8ドルだとすると、Arbitrumで受け取るのは約992 USDCです。ただしArbitrumでトークンを交換するにはETHのガス代が必要なので、事前に少額のETHも一緒に移しておく必要があります。一方、取引所がArbitrumでのUSDC出金に対応していれば、",["出金手数料","withdrawal-fee"],"だけで移せる場合もあります。"],"mistakes":["検索結果から偽のブリッジサイトにアクセスし、ウォレットを接続すること。","移動先のチェーンでガス代用の資産を用意せず、受け取ったトークンを動かせなくなること。","非公式のブリッジで発行されたラップトークンを、公式トークンと同じものだと思い込むこと。"],"faq":[{"q":"ブリッジでの送金にはどれくらい時間がかかりますか？","a":"数分で終わるものから、数時間から数日かかるものまであります。特にオプティミスティック型のレイヤー2から公式ブリッジで戻す場合は、長い待機期間があることが一般的です。"},{"q":"ブリッジと取引所経由ではどちらが良いですか？","a":"取引所が両方のネットワークに対応しているなら、取引所経由の方が手順が簡単なことが多いです。DeFiで直接使いたい場合や取引所が対応していない場合は、ブリッジを使います。"}],"title":"クロスチェーンブリッジとは？仕組みと使い方の注意","description":"クロスチェーンブリッジの意味、ロックとラップトークンの仕組み、ハッキングリスクや移動先のガス代など使うときの注意点を解説します。","related":[["wrapped-token","ラップトークン（Wrapped Token）","ラップトークンとは、ある暗号資産を別のブロックチェーンや規格で使えるようにするため、元の資産を裏付けとして1対1で発行されたトークンです。"],["layer-2","レイヤー2（L2）","レイヤー2（L2）とは、イーサリアムなどのレイヤー1の上で取引をまとめて処理し、その結果をL1に記録することで、手数料を下げ処理を速くする仕組みです。"],["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。"],["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"ja","term":"ステーブルコイン","aka":["stablecoin","ステーブル","米ドル連動通貨"],"short":"ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。","body":[["主な種類は3つあります。現金や短期国債などを裏付けにする法定通貨担保型（",["USDT","usdt"],"、USDCなど）、",["暗号資産","cryptocurrency"],"を過剰担保にする",["暗号資産担保型","crypto-backed-stablecoin"],"（DAIなど）、デリバティブなどの仕組みで価格を安定させる",["合成ドル","synthetic-dollar"],"型です。"],["取引所では、",["BTC","bitcoin"],"/USDTのように取引の基軸通貨として広く使われています。価格変動の大きい暗号資産から一時的に避難したり、取引所間で資金を移したりするのにも便利です。"],["ただし「ステーブル」でも価格が常に1ドルとは限りません。発行体の裏付け資産に不安が生じたり、仕組みが崩れたりすると、連動が外れる",["デペッグ","depeg"],"が起こります。規制も国によって異なり、EUのMiCAでは2024年6月30日からステーブルコイン発行者に関するルールが適用されています。日本でも資金決済法で電子決済手段として位置づけられています。"]],"example":"あなたがBTCを1,000万円分持っていて、相場の変動が大きいと感じ、BTCを売って約6万5,000 USDTに換えたとします（1ドル約154円と仮定）。その後BTCが20%下落しても、USDTの価値はドル建てで約6万5,000ドルのままです。ただし円建てでは為替が影響し、1ドルが144円になれば約936万円となり、BTCの下落は避けられても為替で約6.5%減ります。","mistakes":["ステーブルコインはどれも同じで、発行体や仕組みの違いを気にしないこと。","ドル連動のステーブルコインなら円建てでも価値が変わらないと考えること。","送金時に、発行されているネットワークの違いを確認しないこと。"],"faq":[{"q":"ステーブルコインは本当に1ドルの価値がありますか？","a":"設計上は1ドル前後で取引されるようになっていますが、保証されているわけではありません。裏付け資産や償還の仕組みへの信頼が崩れると、1ドルを下回ることがあります。"},{"q":"ステーブルコインにはどんな種類がありますか？","a":"法定通貨担保型、暗号資産担保型、合成ドル型などがあります。米ドル連動が中心ですが、ユーロや円に連動するものもあります。"}],"title":"ステーブルコインとは？種類と仕組み・リスク","description":"ステーブルコインの意味、法定通貨担保型・暗号資産担保型などの種類、デペッグのリスクや為替の影響をわかりやすく解説します。","related":[["usdt","USDT（テザー）","USDT（テザー）とは、Tether社が発行する米ドル連動型のステーブルコインで、暗号資産取引の基軸通貨として最も広く使われているもののひとつです。"],["usdc","USDC（USDコイン）","USDCとは、米国のCircle社が発行する米ドル連動型のステーブルコインで、現金と米国短期国債などを裏付けに1 USDCが約1ドルになるよう設計されています。"],["depeg","デペッグ（Depeg）","デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。"],["crypto-backed-stablecoin","暗号資産担保型ステーブルコイン","暗号資産担保型ステーブルコインとは、ETHなどの暗号資産をスマートコントラクトに預け入れ、その担保価値を上回らない範囲で発行されるステーブルコインのことです。"],["synthetic-dollar","合成ドル（デルタニュートラル型ステーブルコイン）","合成ドルとは、暗号資産の現物保有と無期限先物のショートを組み合わせて価格変動を相殺し、ドルに近い価値を保つよう設計されたトークンのことです。代表例はEthenaのUSDeです。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDTは米ドルですか？なぜ暗号資産を買う時によく見かけるの？"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
